// Process charter update or polling
let charterSource;
let operation;

if (Object.keys(items[0].json).length > 0) {
  // This is a webhook update
  charterSource = 'webhook';
  operation = 'update';
} else {
  // This is a scheduled poll
  charterSource = 'scheduled';
  operation = 'poll';
}

return [{
  json: {
    charterSource,
    operation,
    timestamp: new Date().toISOString(),
    charterData: items[0].json
  }
}];

// Extract charter content
let charterContent = '';

if (items[0].json && items[0].json.content) {
  // From GitHub API
  charterContent = Buffer.from(items[0].json.content, 'base64').toString('utf-8');
} else if (items[0].json && items[0].json.stdout) {
  // From local file search
  const charterFiles = items[0].json.stdout.split('\n');

  // Use the first found charter file
  if (charterFiles.length > 0 && charterFiles[0] !== 'No charter files found') {
    const filePath = charterFiles[0].split(':')[0];
    // We'll need to read this file in next step
    return [{
      json: {
        charterFilePath: filePath,
        needToReadFile: true
      }
    }];
  }
}

return [{
  json: {
    charterContent,
    needToReadFile: false
  }
}];

// Prepare charter content from local file
return [{
  json: {
    charterContent: items[0].json.stdout,
    needToReadFile: false
  }
}];

// Parse charter into tasks
const charterContent = items[0].json.charterContent;

// Split the charter content into sections
const sections = charterContent.split(/\n#{2,3}\s+/);

// Initialize the tasks array
const tasks = [];

// Process each section to extract tasks
for (const section of sections) {
  if (!section.trim()) continue;

  // Check if this section has tasks (indicated by checkbox markdown)
  const taskLines = section.match(/- \[ \].*?\n/g) || [];

  // Extract the section title from the first line
  const titleMatch = section.match(/^(.+?)\n/);
  const sectionTitle = titleMatch ? titleMatch[1].trim() : 'Unnamed Section';

  // Process each task line
  for (const taskLine of taskLines) {
    const taskDescription = taskLine.replace(/- \[ \]\s*/, '').trim();

    // Extract tags if present
    const tagMatch = taskDescription.match(/#(\w+)/g);
    const tags = tagMatch ? tagMatch.map(tag => tag.substring(1)) : [];

    // Extract priority if present
    const priorityMatch = taskDescription.match(/priority:(high|medium|low)/);
    const priority = priorityMatch ? priorityMatch[1] : 'medium';

    // Extract assignee if present
    const assigneeMatch = taskDescription.match(/@(\w+)/);
    const assignee = assigneeMatch ? assigneeMatch[1] : 'copilot';

    // Create task object
    tasks.push({
      section: sectionTitle,
      description: taskDescription.replace(/#\w+/g, '').replace(/priority:\w+/g, '').replace(/@\w+/g, '').trim(),
      tags,
      priority,
      assignee,
      status: 'pending'
    });
  }
}

return [{
  json: {
    tasks,
    charterTitle: sections[0].split('\n')[0].trim(),
    taskCount: tasks.length
  }
}];

// Compare charter tasks with existing tasks
const charterTasks = items[0].json.tasks;
let existingTasks = [];

if (items[1].json && Array.isArray(items[1].json)) {
  existingTasks = items[1].json;
}

// Find new tasks (in charter but not in existing tasks)
const newTasks = charterTasks.filter(charterTask => {
  return !existingTasks.some(existingTask => 
    existingTask.description === charterTask.description
  );
});

// Find completed tasks (in existing tasks but marked as completed)
const completedTasks = existingTasks.filter(task => task.status === 'completed');

// Find in-progress tasks (in existing tasks, not completed, still in charter)
const inProgressTasks = existingTasks.filter(existingTask => {
  return existingTask.status !== 'completed' && 
         charterTasks.some(charterTask => charterTask.description === existingTask.description);
});

// Tasks to remove (completed and no longer in charter)
const tasksToRemove = completedTasks.filter(completedTask => {
  return !charterTasks.some(charterTask => charterTask.description === completedTask.description);
});

return [{
  json: {
    newTasks,
    inProgressTasks,
    completedTasks,
    tasksToRemove,
    summary: {
      total: charterTasks.length,
      new: newTasks.length,
      inProgress: inProgressTasks.length,
      completed: completedTasks.length,
      toRemove: tasksToRemove.length
    }
  }
}];

// Process summary and create report
const taskSummary = items[0].json.summary;

const report = `# Project Charter Task Processing Report

## Summary
- Total tasks in charter: ${taskSummary.total}
- New tasks created: ${taskSummary.new}
- In-progress tasks: ${taskSummary.inProgress}
- Completed tasks: ${taskSummary.completed}
- Removed tasks: ${taskSummary.toRemove}

## New Tasks
${items[0].json.newTasks.map(task => `- **${task.description}** (Priority: ${task.priority}, Assignee: ${task.assignee})`).join('\n')}

## In-Progress Tasks
${items[0].json.inProgressTasks.map(task => `- **${task.description}** (Status: ${task.status})`).join('\n')}

## Recently Completed Tasks
${items[0].json.completedTasks.map(task => `- ~~**${task.description}**~~`).join('\n')}

## Next Actions
${taskSummary.new > 0 ? '- Code has been automatically generated for new tasks\n- Pull the latest changes and review the auto-generated code\n- Run tests to ensure functionality' : '- No new tasks requiring action'}

Last updated: ${new Date().toISOString()}`;

return [{
  json: {
    report,
    timestamp: new Date().toISOString(),
    totalTasksProcessed: taskSummary.new + taskSummary.inProgress + taskSummary.completed
  }
}];

